# frozen_string_literal: true

# MCP authentication middleware — generated by extendable-rails.
#
# This is a Rack middleware that delegates to ExtendableRails::Mcp::Authentication.
# Customize authentication logic here if needed.
#
# Mount in config/routes.rb:
#
#   authenticated_mcp = Rack::Builder.new do
#     use Mcp::Middleware::Authentication
#     run Rails.application.config.mcp_server
#   end
#   mount authenticated_mcp, at: "/mcp"
#
# Or add to the middleware stack in config/application.rb:
#
#   config.middleware.insert_before 0, Mcp::Middleware::Authentication
#
module Mcp
  module Middleware
    class Authentication
      def initialize(app)
        @app  = app
        @auth = ExtendableRails::Mcp::Authentication.new(app)
      end

      def call(env)
        # Customize authentication logic here if needed.
        # For example, skip auth for health checks:
        #   return @app.call(env) if env["PATH_INFO"] == "/mcp/health"
        @auth.call(env)
      end
    end
  end
end
